<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Universo de Palavras · Dicionário Criativo</title>
<style>
:root{
  --bg:#0d0b14; --panel:#16131f; --ink:#f2ecff; --dim:#9b93b5;
  --accent:#e8b4ff; --accent2:#8be9fd; --line:#3a3350;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{
  background:radial-gradient(1200px 800px at 70% -10%, #1b1430 0%, var(--bg) 55%);
  color:var(--ink);
  font-family:"Spectral", Georgia, serif;
  overflow:hidden;
}
#stage{position:fixed;inset:0}
canvas{display:block}
#hud{
  position:fixed;top:0;left:0;right:0;
  display:flex;align-items:center;gap:16px;
  padding:14px 20px;
  background:linear-gradient(180deg, rgba(13,11,20,.92), rgba(13,11,20,0));
  z-index:5;pointer-events:none;
}
#hud .brand{font-size:15px;letter-spacing:.18em;text-transform:uppercase;color:var(--dim);white-space:nowrap}
#hud .brand b{color:var(--ink);font-weight:600}
#search{
  pointer-events:auto;
  margin-left:auto;
  display:flex;align-items:center;gap:8px;
  background:rgba(22,19,31,.85);
  border:1px solid var(--line);
  border-radius:999px;
  padding:8px 14px;
  min-width:260px;max-width:340px;
}
#search input{
  background:none;border:none;outline:none;color:var(--ink);
  font-family:inherit;font-size:15px;width:100%;
}
#search input::placeholder{color:var(--dim)}
#search .ic{color:var(--dim);font-size:14px}
#sugg{
  position:fixed;top:64px;right:20px;width:300px;z-index:6;
  background:var(--panel);border:1px solid var(--line);border-radius:12px;
  overflow:hidden;display:none;box-shadow:0 12px 40px rgba(0,0,0,.5);
  max-height:50vh;overflow-y:auto;
}
#sugg button{
  display:block;width:100%;text-align:left;background:none;border:none;
  color:var(--ink);font-family:inherit;font-size:14px;padding:10px 14px;cursor:pointer;
}
#sugg button:hover{background:#221c33}
#panel{
  position:fixed;right:20px;bottom:20px;width:340px;max-height:70vh;
  background:var(--panel);border:1px solid var(--line);border-radius:16px;
  padding:20px;overflow:auto;z-index:5;
  box-shadow:0 20px 60px rgba(0,0,0,.55);
  display:none;
}
#panel h2{font-size:26px;font-weight:600;letter-spacing:.02em;margin-bottom:4px;padding-right:24px}
#panel .tema{color:var(--accent2);font-size:13px;letter-spacing:.12em;text-transform:uppercase;margin-bottom:14px}
#panel .lbl{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--dim);margin:14px 0 8px}
#panel .chips{display:flex;flex-wrap:wrap;gap:6px}
#panel .chip{
  background:#221c33;border:1px solid var(--line);border-radius:999px;
  padding:5px 12px;font-size:13px;color:var(--ink);cursor:pointer;
}
#panel .chip:hover{border-color:var(--accent);color:var(--accent)}
#panel .close{
  position:absolute;top:12px;right:14px;background:none;border:none;
  color:var(--dim);font-size:18px;cursor:pointer;
}
#panel .close:hover{color:var(--ink)}
#legend{
  position:fixed;left:20px;bottom:20px;z-index:5;
  background:rgba(22,19,31,.8);border:1px solid var(--line);border-radius:12px;
  padding:12px 16px;font-size:12px;color:var(--dim);line-height:1.7;
}
#legend b{color:var(--ink)}
#hint{
  position:fixed;left:20px;top:64px;z-index:4;color:var(--dim);font-size:13px;
  pointer-events:none;
}
</style>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Spectral:ital,wght@0,400;0,600;1,400&display=swap" rel="stylesheet">
</head>
